  activation_rate REAL,
  day_30_retention REAL,
  support_volume_7d INTEGER,
  nps_score REAL,
  churn_rate REAL,
  mrr_health_ratio REAL,
  custom_metrics TEXT,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
